# What if we split the input by characters first, then process each character as a word?
def wrap_chars(text, width):
    chars = list(text)
    result = []
    cur = ''
    for c in chars:
        extra = len(c) + (1 if cur else 0)
        if len(cur) + extra > width - 1:
            result.append(cur)
            cur = c
        else:
            cur += c

    if cur:
        result.append(cur)
    return result

